#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# fastbox on box5600g: free my old HDD kit test copies, then build S (stock d80596ad1811, ~/work/monero-fcmp) and E (.8,
# public tag e7bae3ecf, ~/work/dot7/fork) natively with identical flags (Release, ARCH native, dynamic, no tests, Ninja,
# -j6, nice), each in a fresh build dir. Copies to ~/work/fastbox/bin/{S,E}/monerod. Marker FBM_BUILD_DONE <ok|FAIL>.
set -u
. ~/.cargo/env
W=~/work/fastbox; L=$W/build.log; mkdir -p $W/bin/S $W/bin/E; : > $L
log() { echo "$(date -u +%FT%TZ) $*" >> $L; }
fail() { log "$*"; log "FBM_BUILD_DONE FAIL"; exit 1; }
log "free before cleanup: $(df --output=avail -BG ~ | tail -1)"
cd ~/work && for d in kit7test kit9test kit10test kit10pkgtest kit13tar kit13test g016kit12pack g016kit12e7 g016kit12test hddkit3-test; do
  [ -d "$d" ] && [ "$(stat -c %U "$d")" = "$USER" ] && rm -rf "$d" && log "removed ~/work/$d"
done
log "free after cleanup: $(df --output=avail -BG ~ | tail -1)"
log "rustc $(rustc --version); cargo $(cargo --version); c++ $(c++ --version | head -1)"
build() {  # <src dir> <commit> <arm>
  cd "$1" || fail "no $1"
  [ -z "$(git status --porcelain --untracked-files=no)" ] || fail "$1 not clean"
  git checkout -q --detach "$2" || fail "checkout $2"
  git submodule update -q --init --recursive >> $L 2>&1 || fail "submodules $3"
  local B=build/fastbox$3
  rm -rf "$B"
  cmake -S . -B "$B" -G Ninja -DCMAKE_BUILD_TYPE=Release -DBUILD_TESTS=OFF -DSTATIC=OFF -DARCH=native >> $L 2>&1 || fail "cmake $3"
  nice -n 5 ninja -C "$B" -j6 daemon >> $L 2>&1 || fail "build $3"
  cp -p "$B/bin/monerod" $W/bin/$3/monerod
  log "$3 $2: $($W/bin/$3/monerod --version | tail -1); sha256 $(sha256sum $W/bin/$3/monerod | cut -c1-16)"
}
cd ~/work/dot7/fork || fail "no fork checkout"
git fetch -q https://github.com/Fountain5405/monerodato.git "refs/tags/v0.19.0.0-beta.3.1-monerodato.8:refs/tags/v0.19.0.0-beta.3.1-monerodato.8" || fail "fetch .8 tag"
[ "$(git rev-parse 'v0.19.0.0-beta.3.1-monerodato.8^{commit}')" = e7bae3ecf45212a4a2f7fa261343611b9628b4aa ] || fail ".8 tag is not on e7bae3ecf"
build ~/work/dot7/fork e7bae3ecf45212a4a2f7fa261343611b9628b4aa E
cd ~/work/dot7/fork && git checkout -q monerodato-v0
build ~/work/monero-fcmp d80596ad18110390b6ca97a77e29aba36f4644c9 S
log "free at end: $(df --output=avail -BG ~ | tail -1)"
log "FBM_BUILD_DONE ok"
